+        break;
+      case 1:
+        pa2_[0] = pa_[1];
+        break;
+      default:
+        BLOSC_TRACE_ERROR("Unhandled size: %d.", size);
+    }
+    memcpy(dest, pa2_, size);
+    free(pa2_);
+  }
